async function exportActa(m:R,drive=false){if(!drive){const a=document.createElement('a');a.href='/api/export?institution='+institution+'&id='+m.id+'&type=acta&format=pdf';document.body.appendChild(a);a.click();a.remove();return;}const {jsPDF}=await import('jspdf');const pdf=new jsPDF();try{if(settings.logo)pdf.addImage(settings.logo,settings.logo.startsWith('data:image/png')?'PNG':'JPEG',175,10,22,22);}catch{}let y=20;const line=(s:string,size=10)=>{pdf.setFontSize(size);const l=pdf.splitTextToSize(s,180);for(const x of l){if(y>274){pdf.addPage();y=20;}pdf.text(x,15,y);y+=size===16?9:5;}};line(m.headerSnapshot?.institution?.name||data.institution.name,16);line('ACTA DE JUNTA DE CURSO',14);line(m.name,12);line('Año lectivo: '+(m.headerSnapshot?.institution?.year||data.institution.year)+' · '+(m.headerSnapshot?.courseName||courseName(m.course||''))+' · Período '+m.period);line('Fecha: '+m.date+' · Hora: '+(m.time||'—'));line('Tutor: '+(m.tutor||'—')+' · Directivo: '+(m.director||'—'));line('Asistentes: '+(m.attendees||[]).map((id:string)=>m.headerSnapshot?.memberLabels?.find((x:any)=>x.id===id)?.name||teacherName(id)).join(', '));y+=5;for(const [label,key] of [['Orden del día','agenda'],['Análisis académico','analysis'],['Acuerdos','agreements']]){line(label,12);line(m[key]||'Sin registro');y+=5;}line('Compromisos',12);commitments.filter(c=>c.meetingId===m.id).forEach(c=>line(c.name+' · '+teacherName(c.responsible)+' · '+c.due+' · '+c.status));if(m.snapshot)line('Acta cerrada: '+new Date(m.closedAt).toLocaleString('es-EC')+' · Información académica conservada en su versión de cierre.');y+=10;line('Firma del tutor: ____________________');line('Firma del directivo: ____________________');const bytes=new Uint8Array(pdf.output('arraybuffer'));if(drive){let binary='';bytes.forEach(x=>binary+=String.fromCharCode(x));try{const r=await api('/api/drive',{institution,action:'document',recordId:m.id,name:'Acta '+m.name+'.pdf',mime:'application/pdf',base64:btoa(binary)});notify('Acta guardada en Google Drive');window.open(r.url,'_blank','noopener');}catch(e:any){setError(e.message);}}else download(bytes,'Acta '+m.name+'.pdf','application/pdf');}
function cleanRosterValue(value:any){return String(value??'').replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();}
function rosterKey(name:string){return cleanRosterValue(name).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();}
function rosterFromRows(rawRows:any[][]){const rows=rawRows.map(row=>row.map(cleanRosterValue)).filter(row=>row.some(Boolean));const headerAt=rows.slice(0,5).findIndex(row=>row.some(cell=>/apellido|nombre|estudiante|alumno|identific|cédula|cedula|dni|código|codigo/i.test(cell)));const header=headerAt>=0?rows[headerAt]:null;const column=(pattern:RegExp)=>header?header.findIndex(cell=>pattern.test(cell)):-1;const fullName=column(/estudiante|alumno|nombre completo/),firstName=column(/^nombres?$/),lastName=column(/^apellidos?$/),identifier=column(/identific|cédula|cedula|dni|código|codigo/);const seen=new Set<string>(),students:any[]=[];for(const row of rows.slice(headerAt>=0?headerAt+1:0)){const cells=row.filter(Boolean);if(!cells.length)continue;let name=fullName>=0?row[fullName]:[lastName>=0?row[lastName]:'',firstName>=0?row[firstName]:''].filter(Boolean).join(' ');let id=identifier>=0?row[identifier]:'';if(!name){const numeric=cells.find(cell=>/^\d{6,}$/.test(cell.replace(/[-. ]/g,'')));id=id||numeric||'';name=cells.filter(cell=>cell!==numeric&&!/^\d+[.)-]?$/.test(cell)).join(' ');}name=cleanRosterValue(name).replace(/^\d+\s*[.)-]\s*/,'');const key=rosterKey(name);if(name.length<3||!/[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]/.test(name)||/^(n[.ºo]?|número|numero|estudiante|alumno|apellidos?|nombres?|curso|paralelo|lista)$/i.test(name)||seen.has(key))continue;seen.add(key);students.push({name,identifier:cleanRosterValue(id)});}return students;}
function rosterFromText(text:string){return rosterFromRows(text.replace(/\r/g,'').split('\n').map(line=>line.split(/\t|;|\|/)));}
async function readImport(file:File){setBusy(true);try{if(file.size>10*1024*1024)throw new Error('El archivo supera el límite de 10 MB.');const extension=(file.name.split('.').pop()||'').toLowerCase();let list:any[]=[];if(extension==='xlsx'){const ExcelJS=(await import('exceljs')).default,wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const source=wb.getWorksheet('INSUMOS I PERIODO');if(source){const students:any[]=[];for(let r=10;r<=source.rowCount;r++){const number=source.getCell(r,2).value,name=source.getCell(r,3).value;if(typeof number==='number'&&typeof name==='string'&&name.trim())students.push({row:r,name:name.trim()});}if(!students.length)throw new Error('No se encontró una nómina en la matriz.');const val=(ws:any,r:number,c:number)=>{const v=ws?.getCell(r,c)?.value;if(typeof v==='number')return v;if(v&&typeof v==='object'&&typeof v.result==='number')return v.result;return null;};const periods=[1,2,3].map((n)=>{const ws=wb.getWorksheet('INSUMOS '+['I','II','III'][n-1]+' PERIODO'),sum=wb.getWorksheet('NOTA EV SUM'),offset=3+(n-1)*9;return students.map(s=>({name:s.name,individual:Array.from({length:9},(_,i)=>val(ws,s.row,i+(n===1?4:3))),group:Array.from({length:9},(_,i)=>val(ws,s.row,i+(n===1?14:13))),exam:val(sum,s.row+1,offset),project:val(sum,s.row+1,offset+1),direct:val(sum,s.row+1,offset+3),reinforcement:val(sum,s.row+1,offset+5),workshop:val(sum,s.row+1,offset+6),makeup:null,observation:''}));});setImportPreview({mode:'matrix',students,periods,file:file.name,format:'Matriz Excel'});setModal({type:'import'});return;}}if(['xlsx','xls','csv'].includes(extension)){const XLSX:any=await import('xlsx'),book=XLSX.read(await file.arrayBuffer(),{type:'array',cellText:true}),sheet=book.Sheets[book.SheetNames[0]];list=rosterFromRows(XLSX.utils.sheet_to_json(sheet,{header:1,defval:''}));}else if(extension==='docx'){const mammoth:any=await import('mammoth'),result=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});list=rosterFromText(result.value);}else if(extension==='pdf'){const pdfjs:any=await import('pdfjs-dist/legacy/build/pdf.mjs'),pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),disableWorker:true}).promise;let text='';for(let pageNo=1;pageNo<=pdf.numPages;pageNo++){const content=await (await pdf.getPage(pageNo)).getTextContent(),lines=new Map<number,string[]>();for(const item of content.items as any[]){const y=Math.round(item.transform?.[5]||0);lines.set(y,[...(lines.get(y)||[]),item.str]);}text+=[...lines.entries()].sort((a,b)=>b[0]-a[0]).map(([,parts])=>parts.join(' ')).join('\n')+'\n';}list=rosterFromText(text);}else if(['txt','tsv'].includes(extension)){list=rosterFromText(await file.text());}else throw new Error('Formato no compatible. Usa Excel (.xlsx, .xls, .csv), Word (.docx), PDF o texto (.txt).');if(!list.length)throw new Error('No se encontraron nombres de estudiantes. Revisa que el archivo contenga una nómina, con un estudiante por fila.');setImportPreview({mode:'roster',students:list,file:file.name,format:extension.toUpperCase()});setModal({type:'import'});}catch(e:any){setError(e.message);}finally{setBusy(false);}}
async function commitImport(courseId:string,assignmentId:string,importGrades=false){if(!admin&&!tutor.includes(courseId))return;setBusy(true);try{const map=new Map<string,string>(students.filter(s=>s.course===courseId).map(s=>[rosterKey(s.name),s.id]));let added=0;for(const s of importPreview.students){const key=rosterKey(s.name);if(!map.has(key)){const r=await api('/api/records',{institution,kind:'student',course:courseId,payload:{name:s.name,identifier:s.identifier||''}});map.set(key,r.id);added++;}}if(importPreview.mode==='matrix'&&importGrades){for(let n=1;n<=3;n++){const existing=gradebooks.find(g=>g.assignmentId===assignmentId&&g.period===n);if(existing)throw new Error('Ya existe información en este período. El importador conserva las matrices existentes.');await api('/api/records',{institution,kind:'gradebook',course:courseId,payload:{assignmentId,period:n,individualNames:Array.from({length:9},(_,i)=>'Actividad '+(i+1)),groupNames:Array.from({length:9},(_,i)=>'Actividad '+(i+1)),closed:false,rows:importPreview.periods[n-1].map((r:any)=>{const {name,...v}=r;return {...v,studentId:map.get(rosterKey(name))};})}});}}await load();setModal(null);setImportPreview(null);notify('Importación completada: '+added+' estudiantes nuevos.');}catch(e:any){setError(e.message);await load();}finally{setBusy(false);}}
async function fillCatalog(){setBusy(true);try{for(const name of starterSubjects)if(!subjects.some(s=>s.name===name))await api('/api/records',{institution,kind:'subject',payload:{name,track:starterSubjects.indexOf(name)<11?'Ciencias':'Técnico',area:starterSubjects.indexOf(name)<11?'Formación general':'Formación técnica'}});await load();notify('Catálogo de asignaturas creado');}catch(e:any){setError(e.message);}finally{setBusy(false);}}
async function bulkAssign(raw:string){if(!admin)return null;const clean=(v:string)=>v.trim(),key=(v:string)=>clean(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),lines=raw.trim().split(/\r?\n/).map(line=>line.split(/\t|;/).map(clean)).filter(row=>row.some(Boolean));if(!lines.length){setError('Pega al menos una fila de distribución.');return null;}const first=lines[0].join(' ').toLowerCase(),rows=/curso|asignatura|docente/.test(first)?lines.slice(1):lines;if(!rows.length){setError('La primera fila contiene encabezados, pero no hay datos para procesar.');return null;}setBusy(true);try{const knownCourses=new Map(courses.map(c=>[key(c.name),c])),knownSubjects=new Map(subjects.map(s=>[key(s.name),s])),knownAssignments=new Set(assignments.map(a=>[a.course,a.subjectId,a.teacherId].join('|')));let created=0,skipped=0;const issues:string[]=[];for(let i=0;i<rows.length;i++){const [courseLabel,trackValue='',specialty='',subjectLabel,area='',teacherValue]=rows[i];if(!courseLabel||!subjectLabel||!teacherValue){issues.push('Fila '+(i+1)+': completa Curso, Asignatura y Docente.');continue;}const teacherKey=key(teacherValue),teacher=members.find(m=>m.status==='aprobada'&&(key(m.email||'')===teacherKey||key(m.name||'')===teacherKey));if(!teacher){issues.push('Fila '+(i+1)+': no se encontró un docente aprobado para “'+teacherValue+'”.');continue;}let courseRecord=knownCourses.get(key(courseLabel));if(!courseRecord){const track=key(trackValue).includes('tecn')?'Técnico':'Ciencias',out=await api('/api/records',{institution,kind:'course',payload:{name:courseLabel,track,specialty}});courseRecord={id:out.id,name:courseLabel,track,specialty};knownCourses.set(key(courseLabel),courseRecord);}let subjectRecord=knownSubjects.get(key(subjectLabel));if(!subjectRecord){const track=courseRecord.track==='Técnico'?'Técnico':'Ciencias',out=await api('/api/records',{institution,kind:'subject',payload:{name:subjectLabel,track,area}});subjectRecord={id:out.id,name:subjectLabel,track,area};knownSubjects.set(key(subjectLabel),subjectRecord);}const assignmentKey=[courseRecord.id,subjectRecord.id,teacher.id].join('|');if(knownAssignments.has(assignmentKey)){skipped++;continue;}await api('/api/records',{institution,kind:'assignment',course:courseRecord.id,payload:{subjectId:subjectRecord.id,teacherId:teacher.id}});knownAssignments.add(assignmentKey);created++;}await load();const message='Distribución procesada: '+created+' asignaciones creadas'+(skipped?', '+skipped+' ya existían':'')+'.';if(issues.length)setError(message+' Revisa: '+issues.slice(0,3).join(' ')+(issues.length>3?' y '+(issues.length-3)+' filas más.':''));else notify(message);return {created,issues};}catch(e:any){setError(e.message);return null;}finally{setBusy(false);}}
function OpenAssignment({a}:{a:R}){const allBooks=gradebooks.filter(g=>g.assignmentId===a.id),st=students.filter(s=>s.course===a.course),done=allBooks.find(g=>g.period===period)?.rows?.filter((r:GradeRow)=>result(r,settings.formative).complete).length||0;return <article className="subject-card"><div className="subject-top"><span className={'subject-icon '+(subjects.find(s=>s.id===a.subjectId)?.track==='Técnico'?'technical':'')}><BookOpen size={23}/></span><span className="pill">{courses.find(c=>c.id===a.course)?.track||'Ciencias'}</span>{admin&&<button className="icon-btn" title="Eliminar asignación" onClick={()=>remove(a)}><Trash2 size={15}/></button>}</div><h3>{subjectName(a.subjectId)}</h3><p>{courseName(a.course||'')} <span className="middot">·</span> {teacherName(a.teacherId)}</p><div className="subject-meta"><span><Users size={15}/>{st.length} estudiantes</span><span>{allBooks.length}/3 períodos</span></div><div className="progress-track"><i style={{width:(st.length?done/st.length*100:0)+'%'}}/></div><div className="subject-bottom"><span>{done?done+' registros completos':'Listo para empezar'}</span><button onClick={()=>{changeAssignment(a.id);navigate('calificaciones');}}>Abrir registro <ArrowUpRight size={16}/></button></div></article>;}
function Empty({title,text,action,label}:{title:string,text:string,action?:()=>void,label?:string}){return <div className="empty"><BookOpen size={32}/><h3>{title}</h3><p>{text}</p>{action&&<button className="btn primary" onClick={action}><Plus size={17}/>{label||'Crear'}</button>}</div>;}
function FilterBar({withAssignment=false}:{withAssignment?:boolean}){return <div className="filter-bar"><label>Curso y paralelo<select value={course} onChange={e=>{if(dirty&&!confirm('¿Cambiar de curso sin guardar?'))return;setCourse(e.target.value);const a=assignments.find(a=>a.course===e.target.value);setAssignment(a?.id||'');}}><option value="">Todos los cursos</option>{courses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>{withAssignment&&<label>Asignatura<select value={assignment} onChange={e=>changeAssignment(e.target.value)}><option value="">Seleccionar asignatura</option>{assignments.filter(a=>!course||a.course===course).map(a=><option key={a.id} value={a.id}>{subjectName(a.subjectId)} · {teacherName(a.teacherId)}</option>)}</select></label>}<label>Período<select value={period} onChange={e=>changePeriod(+e.target.value)}><option value={1}>I período</option><option value={2}>II período</option><option value={3}>III período</option></select></label></div>;}
function GradeInput({r,field,index}:{r:GradeRow,field:string,index?:number}){const value=index===undefined?(r as any)[field]:(r as any)[field]?.[index];const displayValue=value==null?'':Number(value).toFixed(2);return <input className={'grade-input '+(value!==null&&value!==undefined&&value<7?'low':'')} type="text" inputMode="decimal" aria-label={students.find(s=>s.id===r.studentId)?.name+' '+field+' '+(index===undefined?'':index+1)} defaultValue={displayValue} key={r.studentId+field+index+'_'+assignment+'_'+period+'_'+savedAt+'_'+String(value)} disabled={!editable||draft?.closed} onBlur={e=>{if(displayValue!==e.target.value)updateGrade(r.studentId,field,e.target.value,index);}} onPaste={e=>pasteGrid(e,r.studentId,field,index)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();(e.target as HTMLElement).blur();const inputs=Array.from(document.querySelectorAll<HTMLInputElement>('.grade-input:not(:disabled)'));const at=inputs.indexOf(e.target as HTMLInputElement);inputs[at+1]?.focus();}}}/>;}
